using System.Security.Cryptography;
using SCOPX.Infrastructure.Media;
using SCOPX.Infrastructure.Hospitals;
using SCOPX.Infrastructure.Sessions;
using SCOPX.Infrastructure.Users;
using SCOPX.Api.Authentication;
using SCOPX.Api.Security;
namespace SCOPX.Api.Media;
public static class MediaEndpoints
{
 private const long MaxBytes=50*1024*1024;
 private static readonly Dictionary<string,(string Type,string Kind)> Allowed=new(StringComparer.OrdinalIgnoreCase){[".jpg"]=("image/jpeg","image"),[".jpeg"]=("image/jpeg","image"),[".png"]=("image/png","image"),[".webp"]=("image/webp","image"),[".mp4"]=("video/mp4","video"),[".webm"]=("video/webm","video")};
 public static IEndpointRouteBuilder MapMediaEndpoints(this IEndpointRouteBuilder endpoints)
 {
  var g=endpoints.MapGroup("/api/v1/media").RequireRateLimiting("api");
  g.MapGet("/procedure/{procedureId:guid}",async(Guid procedureId,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IMediaRepository repo,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!ReadAllowed(a.Roles))return Results.Forbid();if(!await repo.ProcedureExistsAsync(a.HospitalId,procedureId,ct))return Results.NotFound();return Results.Ok(await repo.ListForProcedureAsync(a.HospitalId,a.UserId,procedureId,ct));});
  g.MapPost("/upload/{procedureId:guid}",async(Guid procedureId,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IMediaRepository repo,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!WriteAllowed(a.Roles))return Results.Forbid();if(!await repo.ProcedureExistsAsync(a.HospitalId,procedureId,ct))return Results.NotFound(new{error="procedure_not_found"});var file=c.Request.Form.Files.FirstOrDefault();if(file is null||file.Length==0||file.Length>MaxBytes)return Results.BadRequest(new{error="invalid_file_size",maxBytes=MaxBytes});var ext=Path.GetExtension(file.FileName);if(!Allowed.TryGetValue(ext,out var spec))return Results.BadRequest(new{error="unsupported_media_type"});var safeName=Path.GetFileName(file.FileName);var mediaId=Guid.NewGuid();var root=c.RequestServices.GetRequiredService<IConfiguration>()["MediaStorage:Root"]??Path.Combine(AppContext.BaseDirectory,"media-store");var key=$"{a.HospitalId:N}/{mediaId:N}{ext.ToLowerInvariant()}";var full=Path.GetFullPath(Path.Combine(root,key.Replace('/',Path.DirectorySeparatorChar)));var rootFull=Path.GetFullPath(root)+Path.DirectorySeparatorChar;if(!full.StartsWith(rootFull,StringComparison.Ordinal)){return Results.BadRequest(new{error="invalid_storage_key"});}Directory.CreateDirectory(Path.GetDirectoryName(full)!);try{await using(var stream=new FileStream(full,FileMode.CreateNew,FileAccess.Write,FileShare.None,81920,FileOptions.Asynchronous|FileOptions.SequentialScan)){await file.CopyToAsync(stream,ct);}string sha;await using(var fs=File.OpenRead(full)){sha=Convert.ToHexString(await SHA256.HashDataAsync(fs,ct)).ToLowerInvariant();}var row=await repo.CreateAsync(a.UserId,new MediaUploadMetadata(a.HospitalId,procedureId,mediaId,key,spec.Kind,safeName,spec.Type,file.Length,sha),ct);if(row is null){File.Delete(full);return Results.Problem(statusCode:500);}return Results.Created($"/api/v1/media/{row.Id}",row);}catch{if(File.Exists(full))File.Delete(full);throw;}}).DisableAntiforgery();
  g.MapGet("/{id:guid}/download",async(Guid id,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IMediaRepository repo,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!ReadAllowed(a.Roles))return Results.Forbid();var found=await repo.FindAsync(a.HospitalId,a.UserId,id,ct);if(found.Asset is null||found.StorageKey is null)return Results.NotFound();var root=c.RequestServices.GetRequiredService<IConfiguration>()["MediaStorage:Root"]??Path.Combine(AppContext.BaseDirectory,"media-store");var full=Path.GetFullPath(Path.Combine(root,found.StorageKey.Replace('/',Path.DirectorySeparatorChar)));var rootFull=Path.GetFullPath(root)+Path.DirectorySeparatorChar;if(!full.StartsWith(rootFull,StringComparison.Ordinal)||!File.Exists(full))return Results.NotFound();return Results.File(full,found.Asset.ContentType,found.Asset.FileName,enableRangeProcessing:found.Asset.MediaType=="video");});
  return endpoints;
 }
 private static async Task<AuthContext?> Resolve(HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,CancellationToken ct){var token=AuthHeaderReader.ReadBearer(c.Request.Headers.Authorization.ToString());if(token is null)return null;var sess=await s.FindActiveByTokenHashAsync(SessionToken.Hash(token),DateTimeOffset.UtcNow,ct);if(sess is null)return null;var user=await u.FindByIdAsync(sess.UserId,ct);if(user is not{Status:"active"})return null;if(!Guid.TryParse(c.Request.Headers["X-Hospital-ID"].ToString(),out var hid))return null;var member=await m.FindActiveForUserAndHospitalAsync(user.Id,hid,ct);return member is null?null:new(user.Id,hid,member.RoleCodes.ToArray());}
 private static bool ReadAllowed(string[] roles)=>roles.Any(x=>new[]{"hospital_admin","doctor","nurse","auditor","endoscopy_technician"}.Contains(x,StringComparer.OrdinalIgnoreCase));
 private static bool WriteAllowed(string[] roles)=>roles.Any(x=>new[]{"hospital_admin","doctor","endoscopy_technician"}.Contains(x,StringComparer.OrdinalIgnoreCase));
 private sealed record AuthContext(Guid UserId,Guid HospitalId,string[] Roles);
}
